-- 067 · Documento del contrato para obras TODO COSTO (plantilla "Contrato estándar con contratista – Todo costo v1.0").
-- Partes: HABITATUM S.A.S. (Contratante, por su representante legal) y el Contratista; el Propietario no es parte ni firma.
-- Nuevo régimen IVA_UTILIDAD (IVA sobre la base gravable = % utilidad × subtotal) y casilla precios_con_iva (los valores
-- unitarios del contrato ya traen el IVA: el documento los presenta sin IVA y el IVA aparte, sin tocar ítems ni cortes).
-- anexos_integrales: lista de documentos que hacen parte integral (Cláusula 3). La plantilla se elige por la modalidad
-- del proyecto. El documento no lee proyectos_finanzas (sin costo, utilidad ni venta). Texto aprobado por Andrés el 21/10/2026.
-- No cambia datos existentes.

alter table public.contrato_documentos
  add column if not exists precios_con_iva boolean not null default false,
  add column if not exists anexos_integrales jsonb not null default '[]'::jsonb;
alter table public.contrato_documentos
  drop constraint if exists contrato_documentos_regimen_check,
  add constraint contrato_documentos_regimen_check check (regimen in ('IVA', 'AIU', 'SIN_IVA', 'IVA_UTILIDAD'));

insert into public.contrato_plantillas (plantilla, version, modalidad, contenido, parametros, vigente)
values ('contrato_obra_contratista_tc', '1.0', 'TODO_COSTO', $tc${"plantilla": "contrato_obra_contratista_tc", "version": "1.0", "fecha_version": "2026-10-21", "modalidad_aplicable": ["todo_costo"], "regla_partes": "Firman HABITATUM S.A.S. (Contratante, por su representante legal) y el Contratista. El Propietario del inmueble no es parte, no firma y no se nombra por su nombre. No se muestran costo, utilidad, venta al cliente ni datos de finanzas del proyecto.", "contratante_fijo": {"razon_social": "HABITATUM S.A.S.", "nit": "900.896.011-0", "rep_legal": "Arq. Andrés David Hincapié Cadavid", "telefono": "321 748 4979", "correo": "direcciondeproyectos@infohabitatum.com"}, "documento": {"encabezado_subtitulo": "Contrato de obra con contratista", "titulo": "CONTRATO DE OBRA – {{actividad_mayusculas}}", "subtitulo": "No. {{numero_contrato}}", "pie_izquierdo": "HABITATUM S.A.S. · Contratante", "cierre": "— Sin texto posterior a esta línea —"}, "partes": {"plantilla": "Entre los suscritos: de una parte, HABITATUM S.A.S., sociedad identificada con NIT 900.896.011-0, representada legalmente por {{rep_legal_habitatum}}, identificado con cédula de ciudadanía No. {{cc_rep_legal_habitatum}} (en adelante el \"Contratante\"); y de la otra, {{contratista_identificacion}} (en adelante el \"Contratista\"), y conjuntamente las \"Partes\", hemos convenido celebrar el presente Contrato de Obra (el \"Contrato\"), que se regirá por las Condiciones Particulares, las Condiciones Generales, sus anexos y, en lo no previsto, por las normas civiles y comerciales aplicables. El Contratista declara ser un empresario independiente, experto en la especialidad objeto de este Contrato, que cuenta con los medios técnicos y humanos para ejecutarla con plena autonomía.", "contratista_persona_natural": "{{NOMBRE_MAYUSCULAS}}, mayor de edad, identificado(a) con cédula de ciudadanía No. {{cedula}}, quien obra en nombre propio", "contratista_persona_juridica": "{{RAZON_SOCIAL}}, sociedad identificada con NIT {{nit}}, representada legalmente por {{rep_legal}}, identificado(a) con cédula de ciudadanía No. {{cc_rep_legal}}"}, "condiciones_particulares": [{"seccion": "1. CONTRATANTE", "campos": [{"clave": "contratante_razon", "etiqueta": "Razón social", "origen": "fijo", "obligatorio": true, "tipo": "fijo", "valor_por_defecto": "HABITATUM S.A.S. – NIT 900.896.011-0"}, {"clave": "contratante_rep", "etiqueta": "Representante legal", "origen": "documento.campos (nombre y cédula)", "obligatorio": true, "tipo": "texto", "valor_por_defecto": "Arq. Andrés David Hincapié Cadavid"}, {"clave": "director_obra", "etiqueta": "Director de Obra", "origen": "proyecto.director_obra", "obligatorio": true, "tipo": "texto", "valor_por_defecto": "Arq. Andrés David Hincapié Cadavid"}, {"clave": "contratante_telefono_fijo", "etiqueta": "Teléfono", "origen": "fijo", "obligatorio": true, "tipo": "fijo", "valor_por_defecto": "321 748 4979"}, {"clave": "contratante_correo_fijo", "etiqueta": "Correo", "origen": "fijo", "obligatorio": true, "tipo": "fijo", "valor_por_defecto": "direcciondeproyectos@infohabitatum.com"}]}, {"seccion": "2. CONTRATISTA", "campos": [{"clave": "contratista_nombre", "etiqueta": "Nombre", "origen": "proveedor.nombre", "obligatorio": true, "tipo": "texto"}, {"clave": "contratista_direccion", "etiqueta": "Dirección", "origen": "proveedor.direccion", "obligatorio": false, "tipo": "texto"}, {"clave": "contratista_telefono", "etiqueta": "Teléfono", "origen": "proveedor.telefono", "obligatorio": false, "tipo": "texto"}, {"clave": "contratista_correo", "etiqueta": "Correo", "origen": "proveedor.correo", "obligatorio": false, "tipo": "texto"}, {"clave": "contratista_regimen", "etiqueta": "Régimen tributario y soporte de cobro", "origen": "proveedor.regimen_iva + soporte_cobro", "obligatorio": true, "tipo": "texto", "nota": "Ej.: \"No responsable de IVA · Cuenta de cobro a nombre de HABITATUM S.A.S.\" o \"Responsable de IVA · Factura electrónica a nombre de HABITATUM S.A.S.\""}, {"clave": "encargado_obra", "etiqueta": "Encargado permanente en obra", "origen": "contrato.encargado_obra", "obligatorio": false, "tipo": "texto"}]}, {"seccion": "3. OBRA", "campos": [{"clave": "proyecto_nombre", "etiqueta": "Proyecto", "origen": "proyecto.nombre", "obligatorio": true, "tipo": "texto"}, {"clave": "proyecto_ubicacion", "etiqueta": "Ubicación", "origen": "proyecto.ubicacion", "obligatorio": true, "tipo": "texto"}]}, {"seccion": "4. OBJETO Y ALCANCE", "campos": [{"clave": "actividad", "etiqueta": "Actividad", "origen": "contrato.actividad", "obligatorio": true, "tipo": "texto"}, {"clave": "alcance", "etiqueta": "Alcance", "origen": "contrato.alcance", "obligatorio": true, "tipo": "texto_largo", "nota": "Debe incluir las frases INCLUYE: ... y NO INCLUYE: ... (materiales, equipos mayores, etc.)"}, {"clave": "suministros_contratante", "etiqueta": "Suministros del Contratante", "origen": "documento.campos (opcional)", "obligatorio": false, "tipo": "texto_largo"}, {"clave": "anexos_integrales", "etiqueta": "Documentos que hacen parte integral", "origen": "documento.anexos_integrales (lista)", "obligatorio": false, "tipo": "texto_largo"}]}, {"seccion": "5. CONDICIONES ECONÓMICAS", "campos": [{"clave": "modalidad_precio", "etiqueta": "Modalidad de precio", "origen": "fijo", "obligatorio": true, "tipo": "fijo", "valor_por_defecto": "Precios unitarios fijos (Anexo 1)"}, {"clave": "subtotal", "etiqueta": "Subtotal (antes de IVA)", "origen": "calculado: Anexo 1", "obligatorio": true, "tipo": "moneda"}, {"clave": "impuesto", "etiqueta": "IVA", "origen": "calculado según régimen (se omite si no hay IVA)", "obligatorio": false, "tipo": "texto"}, {"clave": "valor", "etiqueta": "Valor total estimado del contrato", "origen": "calculado: subtotal + IVA según régimen", "obligatorio": true, "tipo": "moneda"}, {"clave": "valor_letras", "etiqueta": "Valor en letras", "origen": "calculado: valor en letras en español + \" PESOS M/CTE. El valor definitivo resulta de las cantidades ejecutadas.\"", "obligatorio": true, "tipo": "texto"}, {"clave": "regimen", "etiqueta": "Régimen tributario", "origen": "documento.regimen (Sin IVA | IVA | AIU | IVA sobre la utilidad)", "obligatorio": true, "tipo": "lista"}, {"clave": "anticipo_pct", "etiqueta": "Anticipo", "origen": "contrato.anticipo_pct", "obligatorio": true, "tipo": "porcentaje", "valor_por_defecto": 0}, {"clave": "anticipo_valor", "etiqueta": "Valor del anticipo", "origen": "calculado: valor × anticipo_pct (omitir fila si anticipo = 0)", "obligatorio": true, "tipo": "moneda"}, {"clave": "retencion_pct", "etiqueta": "Retención de garantía", "origen": "contrato.retencion_pct", "obligatorio": true, "tipo": "porcentaje", "valor_por_defecto": 0.1}, {"clave": "cortes_pagos", "etiqueta": "Cortes y pagos", "origen": "contrato.cortes_pagos", "obligatorio": true, "tipo": "texto", "valor_por_defecto": "Quincenales. Cada corte aprobado se paga dentro de uno (1) a tres (3) días calendario siguientes a su aprobación y a la entrega de los documentos."}, {"clave": "medio_pago", "etiqueta": "Medio de pago", "origen": "contrato.medio_pago", "obligatorio": true, "tipo": "texto", "valor_por_defecto": "Efectivo o transferencia bancaria a la cuenta del Contratista, según se acuerde para cada corte."}]}, {"seccion": "6. PLAZO Y HORARIO", "campos": [{"clave": "plazo", "etiqueta": "Plazo de ejecución", "origen": "contrato.plazo_texto", "obligatorio": true, "tipo": "texto", "valor_por_defecto": "[N] meses contados a partir de la firma del Contrato"}, {"clave": "horario", "etiqueta": "Horario de la obra", "origen": "proyecto.horario_obra", "obligatorio": true, "tipo": "texto", "valor_por_defecto": "Lunes a viernes de 7:00 a.m. a 5:00 p.m. y sábados de 7:00 a.m. a 12:00 m."}]}, {"seccion": "7. GARANTÍA DE LOS TRABAJOS", "campos": [{"clave": "garantia", "etiqueta": "Garantía de calidad", "origen": "contrato.garantia_meses", "obligatorio": true, "tipo": "texto", "valor_por_defecto": "Doce (12) meses contados desde el Acta de Recibo Final"}, {"clave": "reclamos", "etiqueta": "Atención de reclamos", "origen": "fijo/editable", "obligatorio": true, "tipo": "texto", "valor_por_defecto": "Inicio de la corrección dentro de cinco (5) días hábiles del aviso; urgencias en 24 horas"}]}, {"seccion": "8. FIRMA Y ANEXOS", "campos": [{"clave": "lugar_fecha", "etiqueta": "Lugar y fecha de firma", "origen": "contrato.lugar_firma + contrato.fecha_firma (formato: \"El Retiro, Antioquia, 19 de octubre de 2026\", mes en minúscula)", "obligatorio": true, "tipo": "texto"}, {"clave": "domicilio", "etiqueta": "Domicilio contractual", "origen": "proyecto.municipio", "obligatorio": true, "tipo": "texto"}, {"clave": "anexos", "etiqueta": "Anexos", "origen": "fijo", "obligatorio": true, "tipo": "fijo", "valor_por_defecto": "Anexo 1. Cantidades y precios · Anexo 2. Condiciones técnicas · Planos y especificaciones de la Obra · Documentos de la Cláusula 3"}]}], "regla_campos_vacios": "Un campo opcional sin valor NO se imprime (se omite la fila completa). Nunca imprimir filas en blanco ni marcadores [ ] en el documento final.", "garantias_exigidas": {"columnas": ["Amparo", "%", "Base", "Valor asegurado", "Vigencia"], "valor_asegurado": "% × valor del contrato (anticipo: % × valor del anticipo)", "solo_imprimir_las_que_aplican": true, "opciones": [{"clave": "cumplimiento", "amparo": "Cumplimiento del contrato", "pct": 0.1, "base": "Valor del contrato", "vigencia": "Plazo del contrato + 4 meses", "activa_por_defecto": true}, {"clave": "anticipo", "amparo": "Buen manejo y correcta inversión del anticipo", "pct": 1.0, "base": "Valor del anticipo", "vigencia": "Plazo del contrato + 4 meses", "activa_por_defecto": false}, {"clave": "salarios", "amparo": "Pago de salarios, prestaciones sociales e indemnizaciones laborales", "pct": 0.1, "base": "Valor del contrato", "vigencia": "Plazo del contrato + 3 años", "activa_por_defecto": true}, {"clave": "estabilidad", "amparo": "Estabilidad y calidad de la obra", "pct": 0.2, "base": "Valor final del contrato", "vigencia": "2 años desde el Acta de Recibo Final", "activa_por_defecto": true}, {"clave": "calidad_bienes", "amparo": "Calidad y correcto funcionamiento de los bienes suministrados", "pct": 0.2, "base": "Valor del contrato", "vigencia": "2 años desde el Acta de Recibo Final", "activa_por_defecto": false, "nota": "Activar solo si el contratista suministra materiales o equipos"}, {"clave": "rce", "amparo": "Responsabilidad civil extracontractual", "pct": 0.2, "base": "Valor del contrato", "vigencia": "Plazo del contrato y sus prórrogas", "activa_por_defecto": true}], "nota_al_pie": "Tomador: el Contratista. Asegurado y beneficiario: HABITATUM S.A.S. En responsabilidad civil extracontractual, el Contratista como tomador y asegurado, y HABITATUM S.A.S. y el Propietario como asegurados adicionales. El valor de estabilidad se ajusta al valor final en la liquidación."}, "clausulas": [{"numero": 1, "titulo": "DEFINICIONES", "parrafos": [{"tipo": "parrafo", "texto": "Para efectos del presente Contrato, los siguientes términos tendrán el significado que aquí se les asigna:"}, {"tipo": "literal", "texto": "a) Obra: el proyecto identificado en las Condiciones Particulares, que el Contratante ejecuta para el Propietario."}, {"tipo": "literal", "texto": "b) Director de Obra: la persona designada por el Contratante en las Condiciones Particulares para dirigir la Obra y representarlo frente al Contratista. Es la única instancia autorizada para impartir instrucciones al Contratista. El cambio del Director de Obra se comunicará por escrito."}, {"tipo": "literal", "texto": "c) Propietario: el dueño del inmueble donde se ejecuta la Obra, con quien el Contratante tiene una relación independiente. No es parte de este Contrato."}, {"tipo": "literal", "texto": "d) Trabajos: las actividades, suministros e instalaciones objeto del Contrato, descritos en las Condiciones Particulares, el Anexo 1 (Cantidades y Precios) y el Anexo 2 (Condiciones Técnicas)."}, {"tipo": "literal", "texto": "e) Corte de Obra: medición conjunta, entre el Contratista y el Director de Obra, de los Trabajos ejecutados y recibidos a satisfacción en el periodo pactado, consignada en un acta que sirve de base para el pago."}, {"tipo": "literal", "texto": "f) Liberación: aprobación previa y escrita del Director de Obra, por bitácora, correo electrónico o mensaje escrito, antes de cubrir, vaciar u ocultar un trabajo."}, {"tipo": "literal", "texto": "g) Condiciones Particulares: el acápite II de este documento. En caso de contradicción prevalecen las Condiciones Particulares, luego las Condiciones Generales, luego el Anexo 2, luego el Anexo 1 y luego los documentos de la Cláusula 3."}]}, {"numero": 2, "titulo": "OBJETO", "parrafos": [{"tipo": "parrafo", "texto": "El Contratista se obliga para con el Contratante a ejecutar, por su cuenta y riesgo, con plena autonomía técnica, administrativa y financiera, y con su propio personal y herramienta, los Trabajos descritos en las Condiciones Particulares y en los Anexos 1 y 2, conforme a los planos, especificaciones e instrucciones del Director de Obra. Como contraprestación, el Contratante pagará al Contratista el precio pactado."}]}, {"numero": 3, "titulo": "DOCUMENTOS QUE HACEN PARTE INTEGRAL", "parrafos": [{"tipo": "parrafo", "texto": "Hacen parte integral de este Contrato, además de sus anexos, los documentos relacionados en las Condiciones Particulares, que el Contratista declara conocer y aceptar, en especial el pliego de condiciones con base en el cual presentó su oferta y el cuadro de cantidades y precios aprobados. En lo no regulado por este Contrato se aplicarán dichos documentos; en caso de contradicción, prevalece lo dispuesto en la Cláusula 1, literal g)."}, {"tipo": "parrafo", "texto": "Parágrafo. La oferta del Contratista solo obliga al Contratante en lo que haya sido aprobado y trasladado al Anexo 1. Las condiciones, exclusiones o salvedades de la oferta que no consten en este Contrato no son oponibles al Contratante."}]}, {"numero": 4, "titulo": "ALCANCE Y CONOCIMIENTO DE LA OBRA", "parrafos": [{"tipo": "parrafo", "texto": "El alcance comprende todo lo necesario para entregar los Trabajos completos, terminados y en correcto funcionamiento, aunque no esté expresamente descrito, cuando sea técnicamente indispensable y razonablemente previsible para un contratista experto en la especialidad."}, {"tipo": "parrafo", "texto": "El Contratista declara que visitó la Obra, revisó los planos, especificaciones, cantidades y condiciones de acceso, almacenamiento y horarios, y que su precio incluye todos los costos para ejecutar los Trabajos. No podrá alegar el desconocimiento de estas condiciones para reclamar mayores valores ni plazos."}, {"tipo": "parrafo", "texto": "Parágrafo. Si el Contratista advierte errores, omisiones o inconsistencias en planos o especificaciones, los informará por escrito al Director de Obra antes de ejecutar el trabajo afectado. Lo que ejecute sin consultar será corregido a su costo."}]}, {"numero": 5, "titulo": "VALOR Y PRECIOS", "parrafos": [{"tipo": "parrafo", "texto": "El valor del Contrato es el señalado en las Condiciones Particulares y se rige por precios unitarios fijos: el valor final será el resultado de multiplicar las cantidades realmente ejecutadas, medidas y recibidas a satisfacción por los precios unitarios del Anexo 1. Las mayores o menores cantidades se pagan o descuentan a los mismos precios unitarios."}, {"tipo": "parrafo", "texto": "Los precios son fijos y no reajustables durante el plazo y sus prórrogas, salvo pacto escrito. Incluyen mano de obra, salarios, prestaciones, seguridad social, dotación y elementos de protección personal, la herramienta y los equipos que estén a cargo del Contratista, transporte interno, aseo y retiro de sobrantes, administración, imprevistos, utilidad, pólizas y los tributos a su cargo."}, {"tipo": "parrafo", "texto": "El IVA se liquida según el régimen señalado en las Condiciones Particulares: sobre el valor de los Trabajos (IVA pleno), solo sobre la utilidad en el régimen AIU, o sobre la base gravable equivalente al porcentaje de utilidad pactado (IVA sobre la utilidad). En los dos últimos casos la factura discriminará la base gravable y el IVA."}, {"tipo": "parrafo", "texto": "Parágrafo. Las obras no previstas en el Anexo 1 solo se ejecutarán y pagarán con aprobación escrita previa del Director de Obra, que fije su precio y su efecto en el plazo. Lo ejecutado sin dicha aprobación no será reconocido."}]}, {"numero": 6, "titulo": "FORMA DE PAGO Y CORTES DE OBRA", "parrafos": [{"tipo": "parrafo", "texto": "Los Trabajos se pagarán mediante Cortes de Obra con la periodicidad y el plazo señalados en las Condiciones Particulares, así:"}, {"tipo": "literal", "texto": "a) Al cierre de cada periodo, el Contratista y el Director de Obra medirán conjuntamente en la Obra las cantidades ejecutadas, y el Director de Obra elaborará el acta de Corte de Obra. Solo se pagan Trabajos terminados, medidos y recibidos a satisfacción."}, {"tipo": "literal", "texto": "b) Son requisitos para cada pago: (i) el acta de Corte de Obra firmada por el Director de Obra y el Contratista; y (ii) factura electrónica a nombre de HABITATUM S.A.S., con el IVA discriminado según el régimen pactado, o, si el Contratista no está obligado a facturar, cuenta de cobro a su nombre."}, {"tipo": "literal", "texto": "c) El Contratante pagará al Contratista dentro del plazo señalado en las Condiciones Particulares, contado desde la aprobación del corte y la entrega de los documentos. Mientras los documentos estén incompletos el plazo no corre ni se causan intereses."}, {"tipo": "literal", "texto": "d) De cada pago se descontarán la amortización del anticipo, la retención de garantía, las retenciones tributarias que correspondan y los demás valores a cargo del Contratista."}, {"tipo": "literal", "texto": "e) Los pagos se harán por transferencia bancaria a la cuenta del Contratista o en efectivo, según se acuerde para cada corte. Todo pago en efectivo constará en recibo firmado por el Contratista, que hará parte del acta de corte."}, {"tipo": "parrafo", "texto": "Parágrafo. La aprobación de un corte no implica recibo definitivo ni renuncia a reclamar por defectos. El Propietario no es deudor del precio ni de ninguna suma a favor del Contratista."}]}, {"numero": 7, "titulo": "ANTICIPO", "parrafos": [{"tipo": "parrafo", "texto": "Si en las Condiciones Particulares se pacta anticipo, este se entregará una vez firmado el Contrato y aprobadas las garantías exigidas, con sujeción a las siguientes reglas:"}, {"tipo": "literal", "texto": "a) Se destinará exclusivamente a la Obra. No constituye pago ni transfiere al Contratista la propiedad de esos recursos hasta su amortización."}, {"tipo": "literal", "texto": "b) Se amortizará en cada Corte de Obra en el mismo porcentaje en que fue otorgado sobre el valor del Contrato, de modo que quede amortizado en su totalidad con el último corte."}, {"tipo": "literal", "texto": "c) Si el Contrato termina por cualquier causa con saldo sin amortizar, el Contratista lo reintegrará dentro de los cinco (5) días hábiles siguientes; en su defecto, se compensará con la retención de garantía y con cualquier saldo a su favor."}]}, {"numero": 8, "titulo": "RETENCIÓN DE GARANTÍA", "parrafos": [{"tipo": "parrafo", "texto": "De cada pago se retendrá el porcentaje señalado en las Condiciones Particulares como garantía del cumplimiento del Contrato, de la calidad de los Trabajos y de las obligaciones laborales del Contratista. La retención se devolverá, sin intereses, dentro de los treinta (30) días siguientes a la firma del Acta de Liquidación, previa entrega del paz y salvo de salarios, prestaciones y seguridad social de su personal, de las pólizas de estabilidad exigidas y la atención de los pendientes del recibo final."}, {"tipo": "parrafo", "texto": "Parágrafo. El Contratante podrá aplicar la retención, total o parcialmente, al pago de reparaciones, anticipo no amortizado u obligaciones laborales y de seguridad social insolutas del Contratista."}]}, {"numero": 9, "titulo": "PLAZO", "parrafos": [{"tipo": "parrafo", "texto": "El plazo de ejecución es el señalado en las Condiciones Particulares. El Contratista se ajustará a la programación general de la Obra que defina el Director de Obra y se coordinará con los demás contratistas."}, {"tipo": "parrafo", "texto": "Las prórrogas solo procederán mediante otrosí escrito, solicitadas antes del vencimiento del plazo y por causas no imputables al Contratista, tales como obras no previstas aprobadas, suspensiones ordenadas por el Director de Obra o fuerza mayor debidamente acreditada."}, {"tipo": "parrafo", "texto": "Parágrafo. Si el Contratista presenta atrasos imputables a él, el Director de Obra podrá exigirle aumentar cuadrillas o frentes de trabajo, sin costo adicional, hasta recuperar el atraso."}]}, {"numero": 10, "titulo": "OBLIGACIONES DEL CONTRATISTA", "parrafos": [{"tipo": "parrafo", "texto": "Además de las previstas en otras cláusulas y en el Anexo 2, el Contratista se obliga a:"}, {"tipo": "literal", "texto": "a) Ejecutar los Trabajos con calidad, empleando los materiales y procedimientos especificados, conforme a las normas técnicas aplicables (NSR-10, RETIE cuando corresponda, normas NTC y manuales del fabricante)."}, {"tipo": "literal", "texto": "b) Acatar únicamente las instrucciones del Director de Obra. Las solicitudes del Propietario, sus familiares o terceros se canalizarán a través del Director de Obra; el Contratista no ejecutará trabajos que no le haya ordenado el Contratante."}, {"tipo": "literal", "texto": "c) Designar un encargado permanente en la Obra, con autoridad suficiente para representarlo."}, {"tipo": "literal", "texto": "d) Disponer de personal idóneo, calificado y suficiente para cumplir el plazo."}, {"tipo": "literal", "texto": "e) Cumplir el horario de trabajo establecido para la Obra, señalado en las Condiciones Particulares o el que fije por escrito el Director de Obra. Aunque el Contratista ejecuta los Trabajos a precio y con autonomía, y no por nómina, la presencia y las labores de su personal en la Obra se sujetarán a dicho horario y no a su libre criterio. Los trabajos por fuera de él requerirán autorización previa del Director de Obra."}, {"tipo": "literal", "texto": "f) Solicitar la Liberación del Director de Obra antes de cubrir, vaciar u ocultar cualquier trabajo."}, {"tipo": "literal", "texto": "g) Cuidar y proteger lo ejecutado y las obras de otros contratistas hasta el recibo final, y reparar a su costo los daños que cause a la Obra, al inmueble, a vecinos o a terceros."}, {"tipo": "literal", "texto": "h) Mantener el aseo diario de sus frentes y retirar sobrantes y escombros propios al sitio que indique el Director de Obra."}, {"tipo": "literal", "texto": "i) Cumplir el reglamento interno de la Obra y, cuando aplique, el de la copropiedad o parcelación, incluidos accesos, ruido y manejo de residuos."}, {"tipo": "literal", "texto": "j) Asistir a las reuniones de obra a las que sea citado e informar oportunamente y por escrito los riesgos, defectos o inconsistencias que detecte."}, {"tipo": "literal", "texto": "k) Cumplir sus obligaciones laborales y de seguridad social, y mantener vigentes las garantías del Contrato."}, {"tipo": "literal", "texto": "l) Abstenerse de pernoctar en la Obra, de ingresar personas ajenas a sus labores y de publicar fotografías o videos de la Obra sin autorización escrita."}]}, {"numero": 11, "titulo": "MATERIALES, HERRAMIENTAS Y EQUIPOS", "parrafos": [{"tipo": "literal", "texto": "a) Materiales suministrados por el Contratante: el Contratista los solicitará por escrito al Director de Obra con una anticipación mínima de tres (3) días hábiles; recibirá y firmará las remisiones; responderá por su custodia, buen uso y pérdida desde su entrega; y devolverá los sobrantes. Las pérdidas y los materiales dañados por mal uso se descontarán a precio de reposición."}, {"tipo": "literal", "texto": "b) Materiales a cargo del Contratista, cuando así se indique en las Condiciones Particulares o en el Anexo 1: serán nuevos, de primera calidad, de las referencias aprobadas y con fichas técnicas. El riesgo sobre ellos es del Contratista hasta el recibo de los Trabajos."}, {"tipo": "literal", "texto": "c) Herramientas y equipos: el Contratista aporta su herramienta, en buen estado y con las certificaciones que exija la actividad. Los equipos que, según las Condiciones Particulares, suministre la Obra los recibirá con acta, responderá por su custodia y buen uso mientras estén a su cargo y los devolverá en el estado en que los recibió, salvo el desgaste normal. El Contratante no responde por la pérdida, hurto o daño de las herramientas o pertenencias del Contratista o de su personal."}]}, {"numero": 12, "titulo": "CALIDAD, INSPECCIÓN Y RECHAZO", "parrafos": [{"tipo": "parrafo", "texto": "El Director de Obra podrá inspeccionar los Trabajos en cualquier momento y ordenar los ensayos que considere necesarios. Los Trabajos defectuosos o que no cumplan las especificaciones serán demolidos, retirados o rehechos por el Contratista, a su costo, dentro del plazo que fije el Director de Obra. Si no lo hace, el Contratante podrá ejecutarlos por medio de terceros y descontará su costo más un diez por ciento (10 %) de cualquier saldo a favor del Contratista. La aprobación de cortes o liberaciones no exonera al Contratista de su responsabilidad por defectos o vicios ocultos."}]}, {"numero": 13, "titulo": "PERSONAL E INDEPENDENCIA", "parrafos": [{"tipo": "parrafo", "texto": "El Contratista es un contratista independiente en los términos del artículo 34 del Código Sustantivo del Trabajo. Ejecutará el Contrato con plena autonomía técnica y directiva, y será el único empleador o contratante del personal que vincule. Entre el Contratante, el Propietario y el personal del Contratista no existirá vínculo laboral alguno."}, {"tipo": "literal", "texto": "a) El Contratista afiliará y pagará oportunamente a todo su personal a salud, pensión y riesgos laborales, y pagará salarios no inferiores al mínimo legal, prestaciones sociales e indemnizaciones."}, {"tipo": "literal", "texto": "b) Si el Contratista no acredita el pago de salarios o seguridad social cuando se le solicite, el Contratante podrá retener los pagos y pagar directamente a los trabajadores y a las entidades de seguridad social, con cargo a cualquier saldo a favor del Contratista."}, {"tipo": "literal", "texto": "c) Está prohibido el trabajo de menores de edad."}, {"tipo": "parrafo", "texto": "Parágrafo. El Contratista mantendrá indemnes al Contratante y al Propietario frente a cualquier reclamación laboral o de seguridad social originada en su personal, incluidas las derivadas de la solidaridad prevista en el artículo 34 del Código Sustantivo del Trabajo."}]}, {"numero": 14, "titulo": "SEGURIDAD Y SALUD EN EL TRABAJO", "parrafos": [{"tipo": "parrafo", "texto": "El Contratista cumplirá las normas de seguridad y salud en el trabajo aplicables a su actividad y, cuando aplique, las de trabajo seguro en alturas de la Resolución 4272 de 2021. En especial se obliga a:"}, {"tipo": "literal", "texto": "a) Antes del ingreso de cada trabajador, acreditar su afiliación vigente a la ARL, los certificados de trabajo en alturas cuando aplique y la entrega de dotación y elementos de protección personal."}, {"tipo": "literal", "texto": "b) Reportar de inmediato al Director de Obra, y a la ARL dentro del término legal, todo accidente o incidente de trabajo."}, {"tipo": "parrafo", "texto": "Parágrafo. El Director de Obra podrá suspender actividades o exigir el retiro de trabajadores que incumplan las normas de seguridad, sin que ello genere prórroga del plazo ni costos adicionales."}]}, {"numero": 15, "titulo": "GARANTÍAS Y PÓLIZAS", "parrafos": [{"tipo": "parrafo", "texto": "Dentro de los cinco (5) días hábiles siguientes a la firma, y como requisito para el primer pago, el Contratista constituirá a su costo, con una compañía de seguros vigilada por la Superintendencia Financiera de Colombia y en formato para contratos entre particulares, las garantías indicadas en la sección III, en las que el Contratista figurará como tomador y HABITATUM S.A.S. como asegurado y beneficiario. En la póliza de responsabilidad civil extracontractual el Contratista figurará como tomador y asegurado, y HABITATUM S.A.S. y el Propietario como asegurados adicionales."}, {"tipo": "literal", "texto": "a) Las pólizas deberán ser aprobadas por el Director de Obra y acompañarse del recibo de pago de la prima."}, {"tipo": "literal", "texto": "b) El Contratista ampliará valores y vigencias dentro de los cinco (5) días hábiles siguientes a cualquier otrosí que aumente el valor o el plazo."}, {"tipo": "literal", "texto": "c) La póliza de responsabilidad civil extracontractual incluirá predios, labores y operaciones, responsabilidad civil patronal y contratistas y subcontratistas."}, {"tipo": "parrafo", "texto": "Parágrafo. Las garantías no limitan la responsabilidad del Contratista. Mientras no se entreguen y aprueben no se efectuarán pagos."}]}, {"numero": 16, "titulo": "COMPENSACIÓN Y DESCUENTOS", "parrafos": [{"tipo": "parrafo", "texto": "El Contratista autoriza de manera expresa e irrevocable al Contratante para descontar de cualquier suma a su favor los valores por anticipo no amortizado, reparaciones, pérdida o daño de materiales y equipos, daños a la Obra o a terceros, pagos laborales o de seguridad social efectuados por su cuenta y demás sumas que se deriven de su incumplimiento, operando la compensación conforme al artículo 1714 del Código Civil."}]}, {"numero": 17, "titulo": "ENTREGA, RECIBO Y LIQUIDACIÓN", "parrafos": [{"tipo": "parrafo", "texto": "Terminados los Trabajos, el Director de Obra y el Contratista suscribirán el Acta de Recibo Final, con la lista de pendientes y el plazo para atenderlos; el recibo no implica renuncia a reclamar por vicios ocultos. Dentro de los treinta (30) días siguientes se suscribirá el Acta de Liquidación, con el valor final ejecutado, los pagos, los descuentos y los saldos, previa entrega del paz y salvo de su personal y de la póliza de estabilidad. Si el Contratista no la firma dentro de los diez (10) días hábiles siguientes a su envío, el Contrato podrá liquidarse unilateralmente."}]}, {"numero": 18, "titulo": "GARANTÍA DE LOS TRABAJOS Y POSTVENTA", "parrafos": [{"tipo": "parrafo", "texto": "El Contratista garantiza la calidad y el correcto funcionamiento de los Trabajos durante el plazo señalado en las Condiciones Particulares, contado desde el Acta de Recibo Final, sin perjuicio de las pólizas y de la responsabilidad prevista en el artículo 2060 del Código Civil."}, {"tipo": "literal", "texto": "a) Atenderá cada reclamo iniciando la corrección dentro de los días hábiles señalados en las Condiciones Particulares, contados desde el aviso escrito, y dentro de las veinticuatro (24) horas siguientes en casos urgentes."}, {"tipo": "literal", "texto": "b) Si no lo hace, el Contratante podrá ejecutar la corrección por terceros y cobrar su costo más un diez por ciento (10 %), con cargo a la retención de garantía, las pólizas o cualquier saldo a favor del Contratista."}]}, {"numero": 19, "titulo": "RESPONSABILIDAD E INDEMNIDAD", "parrafos": [{"tipo": "parrafo", "texto": "El Contratista responde por los daños que él, su personal o sus subcontratistas causen a la Obra, al inmueble, a las obras de otros contratistas, a vecinos y a terceros, y conservará la custodia y el riesgo de los Trabajos hasta el recibo final. Mantendrá indemnes al Contratante y al Propietario frente a toda reclamación, sanción o perjuicio que se origine en sus actos u omisiones, y asumirá su defensa."}]}, {"numero": 20, "titulo": "SUSPENSIÓN", "parrafos": [{"tipo": "parrafo", "texto": "El Director de Obra podrá suspender total o parcialmente los Trabajos por necesidades de la Obra, por instrucción del Contratante, por incumplimiento de las normas de seguridad o por fuerza mayor, mediante acta, y el plazo se suspenderá por el mismo tiempo. Las suspensiones no generan pagos por tiempos muertos ni sobrecostos; si una no imputable al Contratista supera treinta (30) días, este podrá pedir la terminación con el pago de lo ejecutado."}]}, {"numero": 21, "titulo": "TERMINACIÓN", "parrafos": [{"tipo": "parrafo", "texto": "El Contrato terminará por las siguientes causas:"}, {"tipo": "literal", "texto": "a) Ejecución total del objeto y firma del Acta de Liquidación."}, {"tipo": "literal", "texto": "b) Mutuo acuerdo de las Partes, que constará por escrito."}, {"tipo": "literal", "texto": "c) Decisión unilateral del Contratante, en cualquier momento, incluida la decisión de suspender definitivamente o no continuar la Obra, con aviso escrito de cinco (5) días hábiles, pagando únicamente lo ejecutado y recibido, sin indemnización por lucro cesante."}, {"tipo": "literal", "texto": "d) Incumplimiento grave del Contratista, entre otros: abandono de la Obra por más de tres (3) días hábiles; atraso imputable superior al quince por ciento (15 %) del plazo; no constituir las garantías; no pagar salarios o seguridad social; incumplimientos reiterados de seguridad; cesión o subcontratación no autorizadas; o inicio de un proceso de insolvencia."}, {"tipo": "literal", "texto": "e) Por el Contratista, en caso de mora del Contratante superior a treinta (30) días en el pago de cortes aprobados, previo requerimiento escrito con diez (10) días hábiles de antelación."}, {"tipo": "parrafo", "texto": "Parágrafo. En la terminación por incumplimiento del Contratista, el Contratante podrá continuar los Trabajos por medio de terceros, y el mayor costo que ello genere y los perjuicios causados serán a cargo del Contratista."}]}, {"numero": 22, "titulo": "CESIÓN Y SUBCONTRATACIÓN", "parrafos": [{"tipo": "parrafo", "texto": "El Contratista no podrá ceder el Contrato ni subcontratar total o parcialmente los Trabajos sin autorización previa y escrita del Director de Obra; aun autorizado, responderá solidariamente por sus subcontratistas."}]}, {"numero": 23, "titulo": "RELACIÓN CON EL PROPIETARIO Y CONFIDENCIALIDAD", "parrafos": [{"tipo": "parrafo", "texto": "El Contratista se relaciona con la Obra únicamente a través del Contratante. En consecuencia:"}, {"tipo": "literal", "texto": "a) No negociará con el Propietario precios, alcances, cambios ni trabajos adicionales en el inmueble, ni le presentará cotizaciones o cuentas de cobro; toda solicitud la remitirá al Director de Obra."}, {"tipo": "literal", "texto": "b) Durante el plazo del Contrato y los doce (12) meses siguientes a su liquidación, no contratará directamente con el Propietario trabajos en el inmueble de la Obra sin autorización escrita del Contratante."}, {"tipo": "literal", "texto": "c) Guardará reserva sobre los precios de este Contrato, los planos, los diseños y la información del Propietario y de la Obra, y no los usará para fines distintos a la ejecución de los Trabajos."}, {"tipo": "parrafo", "texto": "Parágrafo. El incumplimiento de esta cláusula es causal de terminación por incumplimiento grave del Contratista."}]}, {"numero": 24, "titulo": "SOLUCIÓN DE CONTROVERSIAS", "parrafos": [{"tipo": "parrafo", "texto": "Las diferencias que surjan del Contrato se resolverán, en primer lugar, por arreglo directo dentro de los quince (15) días hábiles siguientes a la solicitud escrita de una Parte. Si no hay acuerdo, cualquiera de las Partes podrá acudir a los mecanismos de solución de conflictos y a la jurisdicción ordinaria colombiana."}]}], "firmas": {"texto_previo": "Las Partes manifiestan su conformidad con el presente Contrato, sus Condiciones Particulares, Condiciones Generales y anexos, y lo suscriben en el lugar y la fecha indicados en las Condiciones Particulares.", "bloques": "Un bloque 'EL CONTRATANTE' (HABITATUM S.A.S., NIT, representante legal y C.C.) y un bloque 'EL CONTRATISTA'. El Propietario no firma."}, "anexo_1": {"titulo": "Anexo 1 · Cantidades y precios", "seccion_A": "Cuadro de cantidades y precios (sin IVA): Ítem | Descripción | Un | Cant. | V. unitario | V. total; luego Subtotal, Régimen, la línea de impuesto que corresponda y VALOR TOTAL DEL CONTRATO", "nota_A": "Cantidades estimadas. Se pagan las cantidades realmente ejecutadas, medidas y recibidas, a los precios unitarios fijos de este anexo.", "seccion_B": "Precios unitarios de referencia (sin cantidad contratada): ítems marcados como 'referencia'; muestran solo V. unitario y no suman al valor del contrato", "nota_B": "Solo se ejecutan y pagan con orden escrita previa del Director de Obra que fije la cantidad. Las horas se soportan con planilla diaria firmada por el Director de Obra. No suman al valor del contrato.", "firmas": ["El Contratante", "El Contratista"]}, "anexo_2": {"titulo": "Anexo 2 · Condiciones técnicas", "A_requisitos_previos": ["RUT actualizado del Contratista.", "Copia de la cédula del Contratista (persona natural) o certificado de existencia y representación legal y cédula del representante (persona jurídica).", "Certificación bancaria, cuando los pagos se hagan por transferencia.", "Pólizas exigidas en la sección III del Contrato, con el recibo de pago de la prima.", "Listado del personal con afiliación vigente a salud, pensión y ARL.", "Certificados vigentes de trabajo en alturas, cuando aplique.", "Fichas técnicas y muestras aprobadas, cuando el Contratista suministre materiales."], "B_obligaciones_generales": ["Recibir los frentes y soportes de trabajo mediante acta, dejando constancia de defectos previos. Iniciar un frente sin reportar defectos implica la aceptación del soporte.", "Ejecutar conforme a los planos, especificaciones, NSR-10, normas técnicas aplicables y manuales del fabricante, cumpliendo las tolerancias de plomo, nivel, escuadra y alineamiento especificadas.", "Solicitar la Liberación del Director de Obra antes de cubrir, vaciar u ocultar cualquier trabajo, y antes de iniciar cada frente que la requiera.", "Presentar muestras o ejecutar un tramo de prueba cuando el Director de Obra lo solicite; el trabajo debe igualar la muestra aprobada.", "Coordinar con los demás oficios los elementos embebidos, pases y remates. Prohibido romper, perforar o regatear elementos estructurales sin autorización escrita del Director de Obra.", "Controlar los materiales recibidos: firmar remisiones, almacenarlos en orden, usarlos racionalmente y devolver los sobrantes.", "Proteger lo ejecutado y las obras de otros oficios (carpinterías, aparatos, ventanería, pisos); los daños corren por su cuenta.", "Mantener el aseo diario de sus frentes y retirar los escombros propios al sitio autorizado.", "Realizar con acta las pruebas que exija su actividad (estanqueidad, presión, funcionamiento, nivelación) antes del recibo.", "En trabajos en alturas, cumplir la Resolución 4272 de 2021: personal certificado, permisos de trabajo, anclajes y equipos certificados.", "Corregir a su costo los defectos atribuibles a la ejecución, durante la Obra y el período de garantía.", "Entregar fichas técnicas, garantías del fabricante y manuales de lo suministrado o instalado, cuando aplique.", "Atender los retoques y la lista de pendientes del recibo dentro del plazo fijado en el acta."], "C_obligaciones_particulares": "Lista editable por contrato; numeración continúa después de la sección B. Si está vacía, se omite la sección C.", "cierre": "Lo anterior sin perjuicio de los planos, especificaciones y normas técnicas aplicables, que prevalecen en lo que sean más exigentes.", "firma": "El Contratista – recibido y aceptado"}}$tc$::jsonb,
        (select parametros from public.contrato_plantillas where plantilla = 'contrato_obra_contratista' and version = '1.0'), true)
on conflict (plantilla, version) do nothing;

create or replace function public._plantilla_contrato_vigente(p_modalidad text)
returns uuid language sql stable security definer set search_path = public as $$
  select id from contrato_plantillas
   where vigente and modalidad = coalesce(p_modalidad, 'ADMINISTRACION_DELEGADA')
   order by creado_en desc limit 1;
$$;
revoke all on function public._plantilla_contrato_vigente(text) from public, anon, authenticated;

CREATE OR REPLACE FUNCTION public.documento_contrato_datos(p_contrato uuid)
 RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare c record; v_res jsonb; v_modelo text;
begin
  if auth.uid() is null then raise exception 'Inicie sesión.'; end if;
  select * into c from contratos where id = p_contrato;
  if c.id is null then raise exception 'Contrato no encontrado.'; end if;
  select modelo_contratacion into v_modelo from proyectos where id = c.proyecto_id;
  select jsonb_build_object(
    'contrato', jsonb_build_object('id', c.id, 'numero_contrato', c.numero_contrato, 'concepto', c.concepto,
        'alcance_detallado', c.alcance_detallado, 'fecha_contrato', c.fecha_contrato, 'pct_anticipo', c.pct_anticipo, 'estado', c.estado,
        'valor_inicial', c.valor_inicial, 'fecha_inicio', c.fecha_inicio, 'plazo_valor', c.plazo_valor, 'plazo_unidad', c.plazo_unidad,
        'garantia_meses', c.garantia_meses),
    'proyecto', (select jsonb_build_object('id', p.id, 'nombre', p.nombre, 'codigo', p.codigo, 'cliente', p.cliente,
        'direccion_obra', p.direccion_obra, 'ciudad', p.ciudad, 'modelo_contratacion', p.modelo_contratacion,
        'director_obra', p.director_obra, 'horario_obra', p.horario_obra) from proyectos p where p.id = c.proyecto_id),
    'propietarios', case when v_modelo = 'TODO_COSTO' then '[]'::jsonb
                         else coalesce((select p.propietarios from proyectos p where p.id = c.proyecto_id), '[]'::jsonb) end,
    'proveedor', (select jsonb_build_object('id', v.id, 'nombre', v.nombre, 'nit', v.nit, 'telefono', v.telefono,
        'representante_legal', v.representante_legal, 'tipo_persona', v.tipo_persona, 'cc_representante', v.cc_representante,
        'direccion', v.direccion, 'correo', v.correo, 'regimen_iva', v.regimen_iva, 'soporte_cobro', v.soporte_cobro)
        from proveedores v where v.id = c.contratista_id),
    'items', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'codigo', i.codigo, 'descripcion', i.descripcion,
        'unidad', i.unidad, 'cantidad', i.cantidad, 'valor_unitario', i.valor_unitario, 'referencia', i.referencia)
        order by i.orden, i.codigo) from contrato_items i where i.contrato_id = c.id and not i.es_adicional), '[]'::jsonb),
    'documento', (select to_jsonb(d) - 'snapshot' from contrato_documentos d where d.contrato_id = c.id),
    'snapshot', (select d.snapshot from contrato_documentos d where d.contrato_id = c.id),
    'plantilla', (select jsonb_build_object('id', t.id, 'version', t.version, 'modalidad', t.modalidad, 'contenido', t.contenido, 'parametros', t.parametros)
        from contrato_plantillas t
        where t.id = coalesce((select d.plantilla_id from contrato_documentos d where d.contrato_id = c.id),
                              public._plantilla_contrato_vigente(v_modelo)))
  ) into v_res;
  return v_res;
end $function$;

CREATE OR REPLACE FUNCTION public.guardar_documento_contrato(p_contrato uuid, p_datos jsonb)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare c record; v_estado text; v_plantilla uuid;
begin
  if not public.es_admin() then raise exception 'Solo un administrador puede editar el documento del contrato.'; end if;
  select k.*, p.modelo_contratacion into c from contratos k join proyectos p on p.id = k.proyecto_id where k.id = p_contrato;
  if c.id is null then raise exception 'Contrato no encontrado.'; end if;
  select estado, plantilla_id into v_estado, v_plantilla from contrato_documentos where contrato_id = p_contrato for update;
  if v_estado = 'FIRMADO' then raise exception 'El contrato está firmado y no se puede modificar.'; end if;
  if v_plantilla is null then
    v_plantilla := public._plantilla_contrato_vigente(c.modelo_contratacion);
    if v_plantilla is null then raise exception 'No hay plantilla vigente para este tipo de obra.'; end if;
  end if;
  insert into contrato_documentos (contrato_id, plantilla_id, estado, campos, contratante, regimen, pct_a, pct_i, pct_u, pct_iva,
      anticipo_pct, retencion_pct, garantias, obligaciones, fecha_firma, precios_con_iva, anexos_integrales, actualizado_en, actualizado_por)
  values (p_contrato, v_plantilla, 'BORRADOR',
      coalesce(p_datos->'campos', '{}'::jsonb),
      case when c.modelo_contratacion = 'TODO_COSTO' then '[]'::jsonb else coalesce(p_datos->'contratante', '[]'::jsonb) end,
      coalesce(p_datos->>'regimen', 'SIN_IVA'),
      coalesce((p_datos->>'pct_a')::numeric, 0), coalesce((p_datos->>'pct_i')::numeric, 0),
      coalesce((p_datos->>'pct_u')::numeric, 0), coalesce((p_datos->>'pct_iva')::numeric, 19),
      coalesce((p_datos->>'anticipo_pct')::numeric, 0), coalesce((p_datos->>'retencion_pct')::numeric, 10),
      coalesce(p_datos->'garantias', '[]'::jsonb), coalesce(p_datos->'obligaciones', '[]'::jsonb),
      nullif(p_datos->>'fecha_firma', '')::date,
      coalesce((p_datos->>'precios_con_iva')::boolean, false), coalesce(p_datos->'anexos_integrales', '[]'::jsonb),
      now(), auth.uid())
  on conflict (contrato_id) do update set
      estado = 'BORRADOR', campos = excluded.campos, contratante = excluded.contratante, regimen = excluded.regimen,
      pct_a = excluded.pct_a, pct_i = excluded.pct_i, pct_u = excluded.pct_u, pct_iva = excluded.pct_iva,
      anticipo_pct = excluded.anticipo_pct, retencion_pct = excluded.retencion_pct,
      garantias = excluded.garantias, obligaciones = excluded.obligaciones, fecha_firma = excluded.fecha_firma,
      precios_con_iva = excluded.precios_con_iva, anexos_integrales = excluded.anexos_integrales,
      actualizado_en = now(), actualizado_por = auth.uid();
  if p_datos ? 'referencias' then
    update contrato_items set referencia = (id::text in (select jsonb_array_elements_text(p_datos->'referencias')))
    where contrato_id = p_contrato and not es_adicional;
  end if;
  return public.documento_contrato_datos(p_contrato);
end $function$;

CREATE OR REPLACE FUNCTION public.generar_documento_contrato(p_contrato uuid)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare d record; v_datos jsonb; f jsonb; v_falta text[] := '{}'; o jsonb; v_modelo text;
begin
  if not public.es_admin() then raise exception 'Solo un administrador puede generar el contrato.'; end if;
  select * into d from contrato_documentos where contrato_id = p_contrato for update;
  if d.contrato_id is null then raise exception 'Guarde el documento antes de generarlo.'; end if;
  if d.estado = 'FIRMADO' then raise exception 'El contrato ya está firmado.'; end if;
  select p.modelo_contratacion into v_modelo from contratos k join proyectos p on p.id = k.proyecto_id where k.id = p_contrato;
  f := d.campos;
  if v_modelo = 'TODO_COSTO' then
    if coalesce(trim(f->>'contratante_rep_legal'), '') = '' or coalesce(trim(f->>'contratante_cc_rep'), '') = '' then
      v_falta := array_append(v_falta, 'representante legal de HABITATUM y su cédula'::text); end if;
    if d.regimen = 'IVA_UTILIDAD' and coalesce(d.pct_u, 0) <= 0 then
      v_falta := array_append(v_falta, 'porcentaje de utilidad gravable del régimen IVA sobre la utilidad'::text); end if;
  else
    if jsonb_array_length(d.contratante) = 0 then v_falta := array_append(v_falta, 'propietarios del Contratante'::text); end if;
    for o in select * from jsonb_array_elements(d.contratante) loop
      if coalesce(trim(o->>'nombre'), '') = '' or coalesce(trim(o->>'identificacion'), '') = '' then
        v_falta := array_append(v_falta, 'nombre e identificación de cada propietario'::text); exit; end if;
    end loop;
  end if;
  if coalesce(trim(f->>'contratista_nombre'), '') = '' or coalesce(trim(f->>'contratista_identificacion'), '') = '' then
    v_falta := array_append(v_falta, 'nombre e identificación del Contratista'::text); end if;
  if coalesce(trim(f->>'proyecto_nombre'), '') = '' or coalesce(trim(f->>'proyecto_ubicacion'), '') = '' then
    v_falta := array_append(v_falta, 'proyecto y ubicación'::text); end if;
  if coalesce(trim(f->>'actividad'), '') = '' then v_falta := array_append(v_falta, 'actividad'::text); end if;
  if coalesce(trim(f->>'alcance'), '') = '' then v_falta := array_append(v_falta, 'alcance'::text); end if;
  if coalesce(trim(f->>'plazo'), '') = '' then v_falta := array_append(v_falta, 'plazo'::text); end if;
  if coalesce(trim(f->>'lugar_firma'), '') = '' or d.fecha_firma is null then v_falta := array_append(v_falta, 'lugar y fecha de firma'::text); end if;
  if not exists (select 1 from contrato_items i where i.contrato_id = p_contrato and not i.es_adicional and not i.referencia
                 and coalesce(i.cantidad, 0) > 0 and coalesce(i.valor_unitario, 0) > 0) then
    v_falta := array_append(v_falta, 'al menos un ítem con cantidad y valor'::text); end if;
  if array_length(v_falta, 1) > 0 then raise exception 'Faltan datos obligatorios: %.', array_to_string(v_falta, ', '); end if;
  v_datos := public.documento_contrato_datos(p_contrato) - 'snapshot';
  update contrato_documentos set estado = 'GENERADO', snapshot = v_datos || jsonb_build_object('generado_en', now()),
    generado_en = now(), generado_por = auth.uid() where contrato_id = p_contrato;
  return public.documento_contrato_datos(p_contrato);
end $function$;
